// app.js — Hardened Express application
// Security improvements: input validation, error handling, rate limiting,
// security headers, env-based config, and safe response structure.

'use strict';

const express = require('express');
const helmet  = require('helmet');               // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting

const app  = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Security headers (removes X-Powered-By, adds CSP, HSTS, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing with a strict size limit to prevent payload DoS
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate limiting — 100 requests per 15 minutes per IP across all routes
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Helper: send a consistent, typed success envelope
// ---------------------------------------------------------------------------
function sendSuccess(res, data, statusCode = 200) {
  res.status(statusCode).json({ success: true, data });
}

// ---------------------------------------------------------------------------
// 5. Routes
// ---------------------------------------------------------------------------

// GET /health — no user input, no validation needed
app.get('/health', (_req, res) => {
  sendSuccess(res, { status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — validate & sanitize any accepted query parameters
app.get('/users', (req, res, next) => {
  try {
    // Example: only accept an optional numeric ?page= query param
    const { page } = req.query;

    if (page !== undefined) {
      const pageNum = parseInt(page, 10);

      if (!Number.isInteger(pageNum) || pageNum < 1) {
        return res.status(400).json({
          success: false,
          error: 'Invalid "page" parameter. Must be a positive integer.',
        });
      }
    }

    // Static data — replace with a validated DB call in production.
    // Never interpolate raw query params directly into DB queries; use
    // parameterised queries or an ORM with bound variables instead.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    sendSuccess(res, users);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 6. 404 handler — must be defined after all valid routes
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ success: false, error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 7. Global error handler — 4 arguments signals Express this is an error
//    handler. Never expose internal error details (stack traces) in production.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log full error internally (replace with your logger, e.g. winston/pino)
  console.error('[ERROR]', err);

  const statusCode = err.status || err.statusCode || 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred.'  // Never leak internals in production
      : err.message;                     // Developer-friendly detail locally

  res.status(statusCode).json({ success: false, error: message });
});

// ---------------------------------------------------------------------------
// 8. Start server — only when this file is run directly, not when imported
//    in tests. Prevents port conflicts during unit/integration testing.
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

