// ─── 4. BODY PARSING WITH SIZE LIMIT ─────────────────────────────────────────
// Prevent large payload attacks by enforcing a size cap.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 5. RATE LIMITING ─────────────────────────────────────────────────────────
// Protect all routes from brute-force and DoS attacks.
