'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Security Middleware
// ---------------------------------------------------------------------------

// Set secure HTTP response headers
app.use(helmet());

// Parse JSON bodies with a size limit to prevent payload-based DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Apply rate limiting to all requests
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,     // return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// Input Validation Helper
// ---------------------------------------------------------------------------

/**
 * Validates that a value is a safe positive integer (e.g. for ID params).
 * @param {*} value
 * @returns {number|null} Parsed integer or null if invalid
 */
function parsePositiveInt(value) {
  const parsed = parseInt(value, 10);
  if (Number.isNaN(parsed) || parsed <= 0 || String(parsed) !== String(value)) {
    return null;
  }
  return parsed;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — no sensitive data, safe to be public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Return a safe, allowlisted subset of user fields
app.get('/users', (req, res) => {
  // Simulated data store — replace with real DB calls in production
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Allowlist only the fields safe to expose publicly
  const safeUsers = users.map(({ id, name }) => ({ id, name }));
  res.json(safeUsers);
});

// Example of a parameterized route with input validation
app.get('/users/:id', (req, res) => {
  const userId = parsePositiveInt(req.params.id);
  if (userId === null) {
    return res.status(400).json({ error: 'Invalid user ID. Must be a positive integer.' });
  }

  // Simulated lookup — replace with real DB call in production
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  const user = users.find((u) => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found.' });
  }

  res.json(user);
});

// ---------------------------------------------------------------------------
// Catch-all 404 Handler (must come after all routes)
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// Global Error Handler (must have 4 arguments for Express to recognise it)
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for diagnostics
  console.error('[Unhandled Error]', err);

  // Never expose stack traces or internal details to the client
  res.status(err.status || 500).json({
    error: 'An unexpected error occurred. Please try again later.',
  });
});

// ---------------------------------------------------------------------------
// Server Bootstrap
// ---------------------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

