// Simple application — hardened for security best practices
'use strict';

const express = require('express');

// ── Security middleware (install via npm) ────────────────────────────────────
// npm install helmet express-rate-limit
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ── 1. Security headers ───────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, Strict-Transport-Security, etc.
app.use(helmet());

// ── 2. Body parsing with size limit ──────────────────────────────────────────
// Prevents oversized payload DoS attacks.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ── 3. Global rate limiter ────────────────────────────────────────────────────
// Limits each IP to 100 requests per 15-minute window.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ── Routes ────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── 4. Input validation helper ───────────────────────────────────────────────
/**
 * Validates and sanitises the `page` and `limit` query parameters.
 * Returns null if any value is invalid.
 */
function parsePagination(query) {
  const page  = parseInt(query.page  ?? '1',  10);
  const limit = parseInt(query.limit ?? '10', 10);

  if (
    !Number.isInteger(page)  || page  < 1 ||
    !Number.isInteger(limit) || limit < 1 || limit > 100
  ) {
    return null;
  }

  return { page, limit };
}

// Stub dataset — replace with a real DB query in production.
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

app.get('/users', (req, res) => {
  // ── 5. Input validation ────────────────────────────────────────────────────
  const pagination = parsePagination(req.query);
  if (!pagination) {
    return res
      .status(400)
      .json({ error: 'Invalid pagination parameters. page ≥ 1, 1 ≤ limit ≤ 100.' });
  }

  // ── 6. Authorization placeholder ──────────────────────────────────────────
  // TODO: verify a JWT / session token before returning user data.
  // Example:
  //   const token = req.headers.authorization?.split(' ')[1];
  //   if (!verifyToken(token)) return res.status(401).json({ error: 'Unauthorized' });

  // ── 7. Paginated response ──────────────────────────────────────────────────
  const { page, limit } = pagination;
  const start = (page - 1) * limit;
  const data  = USERS.slice(start, start + limit);

  res.json({
    data,
    meta: {
      page,
      limit,
      total: USERS.length,
      totalPages: Math.ceil(USERS.length / limit),
    },
  });
});

// ── 8. 404 handler ────────────────────────────────────────────────────────────
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ── 9. Global error handler ───────────────────────────────────────────────────
// Must be defined with four parameters so Express recognises it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for diagnostics.
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  // Never leak stack traces or internal details to the client.
  res.status(err.status ?? 500).json({
    error: err.expose ? err.message : 'An internal server error occurred.',
  });
});

// ── Server startup ────────────────────────────────────────────────────────────
// ── 10. Configurable port via environment variable ───────────────────────────
const PORT = parseInt(process.env.PORT ?? '3000', 10);
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

