// Simple application — hardened for security best practices
'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security headers (X-Content-Type-Options, X-Frame-Options, HSTS, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing with a strict size limit to prevent DoS via large payloads
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Global rate limiter — max 100 requests per 15 minutes per IP
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,   // Disable `X-RateLimit-*` headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Routes
// ---------------------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters
    const ALLOWED_PARAMS = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams = receivedParams.filter((p) => !ALLOWED_PARAMS.has(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Invalid query parameter(s): ${invalidParams.join(', ')}`,
      });
    }

    // Validate and sanitise pagination params
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: '`page` must be >= 1 and `limit` must be between 1 and 100.',
      });
    }

    // NOTE: Replace this static list with a real database query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({ page, limit, total: users.length, data: users });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 5. 404 handler — catches all unmatched routes
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global error handler — must have exactly 4 arguments for Express to
//    recognise it as an error handler.
//    NEVER send stack traces or internal details to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error internally (replace with a proper logger in production)
  console.error('[ERROR]', err);

  res.status(err.status || 500).json({
    error: 'An unexpected error occurred. Please try again later.',
  });
});

// ---------------------------------------------------------------------------
// 7. Start server — port sourced from environment, never hardcoded
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[INFO] Server running on port ${PORT}`);
  });
}

module.exports = app;

