// Simple application — hardened for security best practices
'use strict';

const express = require('express');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Body parsing with size limit (prevents large-payload DoS attacks)
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 2. Security headers (install `helmet`: npm install helmet)
//    Adds X-Content-Type-Options, X-Frame-Options, HSTS, CSP, etc.
// ---------------------------------------------------------------------------
try {
  const helmet = require('helmet');
  app.use(helmet());
} catch {
  console.warn('helmet is not installed. Run `npm install helmet` for security headers.');
}

// ---------------------------------------------------------------------------
// 3. Rate limiting (install `express-rate-limit`: npm install express-rate-limit)
//    Prevents brute-force and basic DoS attacks.
// ---------------------------------------------------------------------------
try {
  const rateLimit = require('express-rate-limit');
  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,                  // limit each IP to 100 requests per window
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests. Please try again later.' },
  });
  app.use(limiter);
} catch {
  console.warn('express-rate-limit is not installed. Run `npm install express-rate-limit`.');
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — no sensitive data, safe to expose publicly
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users list — validate and sanitize any query parameters before use
app.get('/users', (req, res, next) => {
  try {
    // Example: validate an optional ?limit= query parameter
    const limit = parseQueryInt(req.query.limit, { min: 1, max: 100, defaultValue: 50 });

    // In a real app, pass `limit` to your database query — never interpolate
    // query params directly into SQL strings.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].slice(0, limit);

    res.json(users);
  } catch (err) {
    next(err); // forward to global error handler
  }
});

// ---------------------------------------------------------------------------
// 4. Catch-all 404 handler — must come after all valid routes
//    Returns JSON (not Express's default HTML) to avoid leaking framework info
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------------------------------------------------------------------------
// 5. Global error handler — catches anything passed to next(err)
//    Never send stack traces or internal details to the client in production
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isProduction = process.env.NODE_ENV === 'production';

  // Always log the full error server-side for debugging
  console.error('[Error]', err);

  const statusCode = Number.isInteger(err.statusCode) ? err.statusCode : 500;

  res.status(statusCode).json({
    error: isProduction
      ? 'An unexpected error occurred.' // hide internals in production
      : err.message,                    // show message in development
  });
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Safely parse an integer query parameter.
 * @param {unknown} value    - Raw query string value
 * @param {object}  options
 * @param {number}  options.min          - Minimum allowed value
 * @param {number}  options.max          - Maximum allowed value
 * @param {number}  options.defaultValue - Fallback when value is absent
 * @returns {number}
 */
function parseQueryInt(value, { min, max, defaultValue }) {
  if (value === undefined || value === null || value === '') {
    return defaultValue;
  }

  const parsed = parseInt(value, 10);

  if (!Number.isInteger(parsed)) {
    const err = new Error(`Invalid query parameter: expected an integer.`);
    err.statusCode = 400;
    throw err;
  }

  if (parsed < min || parsed > max) {
    const err = new Error(`Query parameter out of range: must be between ${min} and ${max}.`);
    err.statusCode = 400;
    throw err;
  }

  return parsed;
}

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} [${process.env.NODE_ENV || 'development'}]`);
});

// Graceful shutdown — avoids dropping in-flight requests on SIGTERM (e.g., in containers)
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Closing HTTP server gracefully...');
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });
});

module.exports = app;

