// app.js — Express application with security best practices applied

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security Headers
//    helmet sets a suite of protective HTTP headers automatically.
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Request Body Parsing — with strict size limit to prevent payload attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate Limiting — limit each IP to 100 requests per 15-minute window
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Port Configuration — read from environment, never hardcoded
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation: reject unexpected query parameters
    const allowedParams = new Set(['page', 'limit']);
    const receivedParams = Object.keys(req.query);
    const invalidParams = receivedParams.filter((p) => !allowedParams.has(p));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        invalid: invalidParams,
        allowed: [...allowedParams],
      });
    }

    // Input validation: pagination bounds
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

    if (page < 1 || !Number.isInteger(page)) {
      return res.status(400).json({ error: '`page` must be a positive integer.' });
    }
    if (limit < 1 || limit > 100 || !Number.isInteger(limit)) {
      return res.status(400).json({ error: '`limit` must be an integer between 1 and 100.' });
    }

    // In a real app this data would come from a database call wrapped in try/catch
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({ page, limit, total: users.length, data: users });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 5. 404 Handler — catches requests to undefined routes
//    Must be placed AFTER all valid route definitions.
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global Error Handler — catches anything forwarded via next(err)
//    The 4-argument signature is required by Express to treat this as an
//    error-handling middleware.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for debugging, but never send stack
  // traces or internal details to the client.
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err.message);

  const statusCode = err.status || err.statusCode || 500;

  res.status(statusCode).json({
    error:
      process.env.NODE_ENV === 'production'
        ? 'An internal server error occurred.' // Safe: no internals exposed
        : err.message,                         // Verbose only in development
  });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------
if (require.main === module) {
  // Only start listening when the file is run directly, not when imported
  // by tests (where app is exported and the test runner controls the port).
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  });
}

module.exports = app;

