  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── 6. Users Endpoint with Input Validation ────────────────────────────────
app.get('/users', (req, res, next) => {
  try {
    // Example: validate an optional ?limit= query param
    const { limit } = req.query;

    if (limit !== undefined) {
      const parsed = parseInt(limit, 10);

      // Reject non-numeric, negative, or excessively large limits
      if (isNaN(parsed) || parsed < 1 || parsed > 100) {
        return res.status(400).json({
          error: 'Invalid query parameter: "limit" must be an integer between 1 and 100.',
        });
      }
    }

    // NOTE: In a real application, this data would come from a database.
    // Access should also be protected by an authentication middleware (e.g. JWT).
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const result = limit ? users.slice(0, parseInt(limit, 10)) : users;
    res.json(result);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ── 7. 404 Handler ─────────────────────────────────────────────────────────
// Catches requests to any route that doesn't exist.
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ── 8. Global Error Handler ────────────────────────────────────────────────
// Catches any error passed to next(err) across all routes.
// IMPORTANT: Never expose internal error details (stack traces) to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()} - ${err.message}`, {
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  const statusCode = err.status || err.statusCode || 500;

  res.status(statusCode).json({
    error: statusCode === 500
      ? 'An unexpected error occurred. Please try again later.' // Never leak internals
      : err.message,
  });
});

// ── 9. Environment-Aware Port ──────────────────────────────────────────────
// Use an environment variable so the port can differ between dev/staging/prod.
const PORT = parseInt(process.env.PORT, 10) || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

---

### 📦 Required New Dependencies

```bash
npm install helmet express-rate-limit morgan
```

---

### 📋 Summary of All Changes

#### 🔴 High Priority
1. **`helmet()`** — Adds ~15 protective HTTP headers in one call (prevents clickjacking, MIME sniffing, etc.).
2. **`express-rate-limit`** — Caps requests per IP/window to neutralize DoS and brute-force attacks.

#### 🟠 Medium Priority
3. **Body size limit** (`limit: '10kb'`) — Prevents memory exhaustion from large request payloads.
4. **Input validation on query params** — The `?limit=` param is sanitized with `parseInt` and range-checked before use. Apply this pattern to *all* user-supplied inputs.
5. **Global error handler** (`err, req, res, next`) — Centralizes error responses and critically **never leaks stack traces or internal messages** to the client.
6. **404 handler** — Gives a clean, consistent response for unknown routes instead of Express's default HTML error page.

#### 🟡 Low Priority
7. **`morgan` logging** — Structured request logs are essential for detecting anomalies and for incident response.
8. **`process.env.PORT`** — Hardcoded ports are a deployment anti-pattern; environment variables allow proper config across environments.
9. **Authentication note** — The `/users` endpoint should be protected by auth middleware (e.g., JWT via `passport` or `express-jwt`) in any real application. User data should never be publicly accessible.

