/**
 * app.js — Express application with security best practices applied.
 *
 * Improvements over original:
 *  - Helmet for secure HTTP headers
 *  - Rate limiting to prevent abuse
 *  - Centralised error handling (no stack traces leaked to clients)
 *  - Input validation with allowlisting on all query parameters
 *  - Environment-driven configuration (port, etc.)
 *  - Request logging for audit trails
 *  - Explicit JSON body-parser limit to prevent payload attacks
 */

'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security Headers
//    helmet sets ~15 protective HTTP headers in one call (CSP, HSTS, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body Parsing — enforce a strict size limit to prevent payload attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate Limiting — limit each IP to 100 requests per 15-minute window
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in `RateLimit-*` headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Minimal request logging (replace with a proper logger such as pino/winston
//    in production — never log sensitive headers or bodies here)
// ---------------------------------------------------------------------------
app.use((req, _res, next) => {
  // Log method, path, and timestamp only — no query strings or bodies which
  // may contain sensitive data.
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health — no parameters expected; any extras are ignored
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users — demonstrates allowlist-based query-parameter validation.
//
// Accepted parameters:
//   ?id=<positive integer>   — filter by user ID
//
// All other query parameters are rejected with 400 to prevent injection
// or enumeration via unexpected inputs.
app.get('/users', (req, res, next) => {
  try {
    const ALLOWED_PARAMS = new Set(['id']);

    // Reject any query parameter not on the allowlist
    const unknownParams = Object.keys(req.query).filter(
      (key) => !ALLOWED_PARAMS.has(key),
    );
    if (unknownParams.length > 0) {
      return res.status(400).json({
        error: `Unknown query parameter(s): ${unknownParams.join(', ')}`,
      });
    }

    // Validate `id` if provided
    let filterId = null;
    if (req.query.id !== undefined) {
      const parsed = Number(req.query.id);
      if (!Number.isInteger(parsed) || parsed <= 0) {
        return res.status(400).json({
          error: '`id` must be a positive integer.',
        });
      }
      filterId = parsed;
    }

    // In a real application this data would come from a parameterised database
    // query — never via string interpolation.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const result = filterId
      ? users.filter((u) => u.id === filterId)
      : users;

    // 404 when filtering by a specific ID that doesn't exist
    if (filterId !== null && result.length === 0) {
      return res.status(404).json({ error: 'User not found.' });
    }

    return res.json(result);
  } catch (err) {
    next(err); // forward unexpected errors to the centralised handler
  }
});

// ---------------------------------------------------------------------------
// 5. 404 Handler — catches requests to undefined routes
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// ---------------------------------------------------------------------------
// 6. Centralised Error Handler
//    Must have exactly four parameters so Express recognises it as an error
//    handler. Never expose err.stack or internal details to the client.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log the full error server-side for diagnostics
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err);

  // Return a generic message to the client — no stack traces, no internals
  res.status(500).json({ error: 'An unexpected error occurred.' });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------
const PORT = Number(process.env.PORT) || 3000;

// Only start listening when this file is the entry point, not when imported
// by tests (which require the module directly).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

