// Simple application - hardened for security best practices

const express = require('express');
const app = express();

// ─── Configuration ────────────────────────────────────────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;
const MAX_PAGE_SIZE = 100;

// ─── Security Middleware ───────────────────────────────────────────────────────

// [1] Parse JSON bodies with a size limit to prevent payload flooding attacks.
app.use(express.json({ limit: '10kb' }));

// [2] Set baseline security headers on every response.
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.removeHeader('X-Powered-By'); // Don't advertise Express version
  next();
});

// [3] Basic rate limiting — replace with a package like `express-rate-limit`
//     in production for persistent, distributed rate limiting.
const requestCounts = new Map();
const RATE_LIMIT_WINDOW_MS = 60 * 1000; // 1 minute
const RATE_LIMIT_MAX = 60;              // max 60 requests per window per IP

app.use((req, res, next) => {
  const ip = req.ip;
  const now = Date.now();
  const entry = requestCounts.get(ip) || { count: 0, windowStart: now };

  if (now - entry.windowStart > RATE_LIMIT_WINDOW_MS) {
    // Reset window
    entry.count = 1;
    entry.windowStart = now;
  } else {
    entry.count += 1;
  }

  requestCounts.set(ip, entry);

  if (entry.count > RATE_LIMIT_MAX) {
    return res.status(429).json({
      error: 'Too many requests. Please try again later.',
    });
  }

  next();
});

// ─── Input Validation Helpers ─────────────────────────────────────────────────

/**
 * Validates and coerces a query parameter to a positive integer.
 * Returns null if the value is missing/invalid.
 * @param {string|undefined} value
 * @param {number} defaultVal
 * @param {number} max
 */
function parsePositiveInt(value, defaultVal, max) {
  if (value === undefined || value === null) return defaultVal;
  const parsed = parseInt(value, 10);
  if (isNaN(parsed) || parsed < 1) return null; // signal invalid input
  return Math.min(parsed, max);
}

// ─── Routes ───────────────────────────────────────────────────────────────────

// [4] Health check — no sensitive data, safe to be public.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// [5] Users list — with input validation and field filtering.
//     TODO: Add authentication/authorization middleware before this route
//           (e.g., app.get('/users', requireAuth, (req, res) => {...}))
app.get('/users', (req, res) => {
  // Validate optional pagination query params
  const page = parsePositiveInt(req.query.page, 1, Infinity);
  const pageSize = parsePositiveInt(req.query.pageSize, 10, MAX_PAGE_SIZE);

  if (page === null || pageSize === null) {
    return res.status(400).json({
      error: 'Invalid pagination parameters. "page" and "pageSize" must be positive integers.',
    });
  }

  // NOTE: In a real app this data comes from a database; never expose raw DB
  // records. Always project only the fields the client actually needs.
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Return only non-sensitive fields (omit e.g. passwords, internal flags)
  const safeUsers = allUsers.map(({ id, name }) => ({ id, name }));

  const start = (page - 1) * pageSize;
  const paginated = safeUsers.slice(start, start + pageSize);

  res.json({
    data: paginated,
    meta: {
      page,
      pageSize,
      total: safeUsers.length,
    },
  });
});

// ─── Error Handlers ───────────────────────────────────────────────────────────

// [6] Catch-all 404 for undefined routes — avoids leaking framework info via
//     Express's default HTML error page.
app.use((req, res) => {
  res.status(404).json({ error: 'Not found.' });
});

// [7] Global error handler — catches errors passed via next(err) or thrown in
//     async routes (with an async wrapper). Never expose stack traces in prod.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const isProduction = process.env.NODE_ENV === 'production';

  // Always log the full error server-side for diagnostics
  console.error('[ERROR]', err);

  res.status(err.status || 500).json({
    error: isProduction
      ? 'An unexpected error occurred.'  // safe, generic message in prod
      : err.message,                     // detailed message in dev/test
  });
});

// ─── Server Bootstrap ─────────────────────────────────────────────────────────

// Only start the server when this file is run directly, not when imported by
// tests (which import via require/module.exports).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

